package com.ruoyi.paicli.service;
import com.ruoyi.paicli.domain.*;
import com.ruoyi.system.secret.ManagedSecretService;
import java.util.*;

/** 管理员明确发布的固定平台模型，不把任意个人配置隐式共享给其他用户。 */
public final class PcModelRelease {
    private PcModelRelease(){}
    public static long releaseVersion(PcStore store,PcRecord release){return store.data(release).get("releaseDefinitionVersion") instanceof Number n?n.longValue():release.getVersion();}
    public static boolean chat(PcStore store,PcRecord release){return !PcEmbeddingPolicy.embedding(store,release)&&!"DEFAULT_SELECTION".equals(release.getKind());}
    private static void clearDefault(PcStore store,String kind,boolean selected,String target){
        if(!selected)return;store.mapper.ensureDefaultSelection(kind,store.clock.instant());
        if(store.mapper.findKey(PcTable.MODEL_RELEASE,"default-selection:"+kind,true)==null)throw PcException.conflict("默认能力选择锁未准备");
        for(PcRecord previous:store.mapper.publishedReleasesForUpdate())if((kind.equals("CHAT")?chat(store,previous):PcEmbeddingPolicy.embedding(store,previous))&&Boolean.TRUE.equals(store.data(previous).get("defaultModel"))&&!Objects.equals(target,previous.getUniqueKey())){previous=store.require(PcTable.MODEL_RELEASE,previous.getId(),true);Map<String,Object> data=store.data(previous);data.putIfAbsent("releaseDefinitionVersion",previous.getVersion());data.put("defaultModel",false);store.save(PcTable.MODEL_RELEASE,previous,data);}
    }
    private static Map<String,Object> publishEmbedding(PcStore store,PcIdempotency idem,ManagedSecretService secrets,long user,String key,Map<String,Object> input){
        PcPersonalService.rejectLegacy(input);return idem.run("user:"+user+":embedding-release",key,input,()->{
            if(!Boolean.TRUE.equals(input.get("confirmSharing")))throw PcException.deny("须明确确认向量发布的受众和凭据共享用途");
            PcRecord settings=store.mapper.findKey(PcTable.PERSONAL_SETTINGS,"owner:"+user,true);if(settings==null)throw PcException.invalid("个人向量配置尚未准备");Map<String,Object> own=store.data(settings),config=PcJson.object(own,"embeddingConfig");PcEmbeddingPolicy.validate(config);
            int sv=PcEmbeddingPolicy.secretVersion(secrets,config,user);String hash=PcEmbeddingPolicy.fingerprint(store,config);long cv=PcEmbeddingPolicy.definition(own);
            if(PcJson.number(input,"configurationVersion")!=cv||!hash.equals(PcJson.text(input,"configFingerprint"))||PcJson.number(input,"expectedDimensions")!=PcJson.number(config,"expectedDimensions"))throw PcException.conflict("向量发布须绑定已核对的当前配置身份");
            if(!PcEmbeddingPolicy.verified(store,settings,config,sv))throw new PcException(422,"PC_EMBEDDING_UNVERIFIED","发布须先完成当前向量配置验证");
            String audience=PcJson.text(input,"audience");List<?> users=input.get("userIds") instanceof List<?> ids?ids:List.of();if(!Set.of("AUTHENTICATED","USERS").contains(audience)||audience.equals("USERS")&&(users.isEmpty()||users.size()>10000||users.stream().anyMatch(id->!String.valueOf(id).matches("[1-9][0-9]{0,17}"))))throw PcException.invalid("须明确发布受众");
            boolean isDefault=Boolean.TRUE.equals(input.get("defaultModel"));clearDefault(store,"EMBEDDING",isDefault,"embedding:"+user);
            Map<String,Object> data=new LinkedHashMap<>();data.put("releaseKind","EMBEDDING");data.put("provider",config.get("provider"));data.put("model",config.get("model"));data.put("configurationVersion",cv);data.put("configFingerprint",hash);data.put("expectedDimensions",config.get("expectedDimensions"));data.put("secretVersion",sv);data.put("verification",own.get("embeddingVerification"));data.put("sourceOwnerId",String.valueOf(user));data.put("audience",audience);data.put("userIds",users.stream().map(String::valueOf).toList());data.put("defaultModel",isDefault);
            PcRecord release=store.mapper.findKey(PcTable.MODEL_RELEASE,"embedding:"+user,true);if(release==null)release=store.insert(PcTable.MODEL_RELEASE,null,user,settings.getId(),null,null,"EMBEDDING_RELEASE","PUBLISHED","embedding:"+user,data);else{if(!input.containsKey("releaseVersion"))throw new PcException(428,"PC_VERSION_REQUIRED","重新发布须核对releaseVersion");store.version(release,PcJson.number(input,"releaseVersion"));data.put("releaseDefinitionVersion",release.getVersion()+1);release.setState("PUBLISHED");store.save(PcTable.MODEL_RELEASE,release,data);}Map<String,Object> result=store.view(release);result.put("kind","EMBEDDING");return result;
        });
    }
    public static PcRecord active(PcStore store,PcRecord model,long user){
        if(Objects.equals(model.getOwnerId(),user))return null;
        PcRecord release=store.mapper.findKey(PcTable.MODEL_RELEASE,"model:"+model.getId(),false);
        if(release==null||!chat(store,release)||!"PUBLISHED".equals(release.getState()))throw PcException.deny("模型未发布给当前用户");
        Map<String,Object> data=store.data(release);boolean allowed="AUTHENTICATED".equals(data.get("audience"))||data.get("userIds") instanceof List<?> ids&&ids.stream().map(String::valueOf).anyMatch(String.valueOf(user)::equals);
        if(!allowed||!Objects.equals(release.getOwnerId(),model.getOwnerId())||PcJson.number(data,data.containsKey("modelDefinitionVersion")?"modelDefinitionVersion":"modelVersion")!=PcSub2ApiPolicy.modelDefinition(store.data(model),model.getVersion()))throw PcException.deny("平台模型受众或固定版本已失效");
        PcRecord provider=store.require(PcTable.PROVIDER_CONFIG,PcJson.number(store.data(model),"providerId"),false);
        long providerVersion=store.data(provider).get("configurationVersion") instanceof Number n?n.longValue():provider.getVersion();
        if(!Objects.equals(provider.getOwnerId(),model.getOwnerId())||PcJson.number(data,"providerVersion")!=providerVersion)throw PcException.deny("平台供应商固定版本已改变，请管理员重新发布");
        return release;
    }
    public static PcRecord model(PcStore store,long id,long user){PcRecord model=store.require(PcTable.MODEL_CONFIG,id,false);active(store,model,user);if(model.getWorkspaceId()!=null&&model.getDirectoryContextId()==null)throw new PcException(409,"PC_LEGACY_READ_ONLY","历史模型不能用于新执行");return model;}
    public static List<PcRecord> visible(PcStore store,long user){List<PcRecord> result=new ArrayList<>(store.mapper.list(PcTable.MODEL_CONFIG,null,user,null,null).stream().filter(m->m.getWorkspaceId()==null).toList());for(PcRecord release:store.mapper.list(PcTable.MODEL_RELEASE,null,null,null,"PUBLISHED")){if(!chat(store,release))continue;PcRecord model=store.require(PcTable.MODEL_CONFIG,PcJson.number(store.data(release),"modelId"),false);if(Objects.equals(model.getOwnerId(),user))continue;try{active(store,model,user);result.add(model);}catch(PcException hidden){}}return result;}
    public static Map<String,Object> publicMetadata(PcStore store,PcRecord model){Map<String,Object> result=new LinkedHashMap<>();Map<String,Object> data=store.data(model);for(String field:List.of("modelId","providerId","displayName","name","contextWindow","supportsImages","supportsThinking","supportsTools","capabilityKnown","enabled","maxOutputTokens","imageInput","thinking","reasoningEffort","reasoningHistory","dsml","template","temperature","maxTokens"))if(data.containsKey(field))result.put(field,data.get(field));result.put("id",String.valueOf(model.getId()));result.put("version",model.getVersion());result.put("ownerUserId",String.valueOf(model.getOwnerId()));result.put("state",model.getState());return result;}
    public static Map<String,Object> publicModel(PcStore store,PcRecord model,long user){PcRecord release=active(store,model,user);Map<String,Object> result=release==null?store.view(model):publicMetadata(store,model);if(release!=null){if(!releasedImages(store,model,user)){result.put("supportsImages",false);result.put("imageInput",false);}result.put("platformModel",true);result.put("releaseId",String.valueOf(release.getId()));result.put("releaseVersion",releaseVersion(store,release));result.put("releaseCasVersion",release.getVersion());}return result;}
    public static Map<String,Object> publicProvider(PcStore store,PcRecord provider){Map<String,Object> result=new LinkedHashMap<>();Map<String,Object> data=store.data(provider);for(String field:List.of("provider","name","wireApi","baseUrl"))if(data.containsKey(field))result.put(field,data.get(field));result.put("id",String.valueOf(provider.getId()));result.put("ownerUserId",String.valueOf(provider.getOwnerId()));result.put("version",store.data(provider).get("configurationVersion") instanceof Number n?n.longValue():provider.getVersion());return result;}
    public static boolean releasedImages(PcStore store,PcRecord model,long user){Map<String,Object> md=store.data(model);if(!md.containsKey("providerId")||!PcSub2ApiPolicy.applies(store.data(store.require(PcTable.PROVIDER_CONFIG,PcJson.number(md,"providerId"),false))))return true;PcRecord release=active(store,model,user);if(release==null)return true;Map<String,Object> data=store.data(release);return data.get("imageVerification") instanceof Map<?,?>&&Objects.equals(store.json.hash(data.get("imageVerification")),store.json.hash(store.data(model).get("imageVerification")));}
    public static void bind(PcStore store,PcRecord model,long user,Map<String,Object> task){PcRecord release=active(store,model,user);if(release!=null){task.put("modelReleaseId",String.valueOf(release.getId()));task.put("modelReleaseVersion",releaseVersion(store,release));task.put("modelSecretOwnerId",String.valueOf(model.getOwnerId()));}}
    public static void verifyTask(PcStore store,PcRecord task){Map<String,Object> data=store.data(task);if(!data.containsKey("modelId")||"0".equals(String.valueOf(data.get("modelId"))))return;PcRecord model=model(store,PcJson.number(data,"modelId"),task.getOwnerId());PcRecord release=active(store,model,task.getOwnerId());if(release!=null&&(!data.containsKey("modelReleaseId")||PcJson.number(data,"modelReleaseId")!=release.getId()||PcJson.number(data,"modelReleaseVersion")!=releaseVersion(store,release)))throw PcException.deny("任务固定的平台模型发布已撤销或改变");}
    public static void verifySecretVersion(PcStore store,PcRecord model,long user,int version){PcRecord release=active(store,model,user);if(release!=null&&PcJson.number(store.data(release),"secretVersion")!=version)throw PcException.conflict("平台模型凭据版本已改变，请管理员重新发布");}
    public static Map<String,Object> publish(PcStore store,PcIdempotency idem,ManagedSecretService secrets,long user,String key,Map<String,Object> input){
        if("EMBEDDING".equals(input.get("kind")))return publishEmbedding(store,idem,secrets,user,key,input);
        if(input.containsKey("kind")&&!"CHAT".equals(input.get("kind")))throw PcException.invalid("发布种类须为CHAT或EMBEDDING");
        PcPersonalService.rejectLegacy(input);return idem.run("user:"+user+":model-release",key,input,()->{
            if(!Boolean.TRUE.equals(input.get("confirmSharing")))throw PcException.deny("发布前须明确确认指定受众可使用该模型与固定凭据");
            PcRecord model=store.require(PcTable.MODEL_CONFIG,PcJson.number(input,"modelId"),true);if(!Objects.equals(model.getOwnerId(),user)||model.getWorkspaceId()!=null)throw PcException.deny("只能显式发布管理员本人当前模型");store.version(model,PcJson.number(input,"modelVersion"));
            PcRecord provider=store.require(PcTable.PROVIDER_CONFIG,PcJson.number(store.data(model),"providerId"),false);if(!Objects.equals(provider.getOwnerId(),user))throw PcException.deny("供应商归属不匹配");String ref=PcJson.text(store.data(provider),"secretRef");var metadata=secrets.metadata("AI",ref);if(!ref.startsWith("ai.paicli.user."+user+".")||!"paicli".equals(metadata.projectCode())||!"ACTIVE".equals(metadata.status())||metadata.activeVersion()==null)throw PcException.deny("当前固定模型凭据尚未准备");
            if(!Boolean.TRUE.equals(store.data(model).get("enabled"))||Set.of("FROZEN","REVOKED_IMPORT").contains(model.getState())||Set.of("FROZEN","REVOKED_IMPORT").contains(provider.getState()))throw PcException.deny("只能发布当前启用的模型与供应商");
            if(PcSub2ApiPolicy.applies(store.data(provider))){PcSub2ApiPolicy.validateMetadata(metadata,ref,user);long definition=store.data(provider).get("configurationVersion") instanceof Number n?n.longValue():provider.getVersion();if(!PcSub2ApiPolicy.verified(store.data(model),model.getVersion(),store.data(provider),definition,metadata.activeVersion()))throw new PcException(422,"PC_MODEL_UNVERIFIED","平台发布须先完成当前Sub2API兼容验证");}
            String audience=PcJson.text(input,"audience");List<?> users=input.get("userIds") instanceof List<?> list?list:List.of();if(!Set.of("AUTHENTICATED","USERS").contains(audience)||audience.equals("USERS")&&(users.isEmpty()||users.size()>10000||users.stream().anyMatch(id->!String.valueOf(id).matches("[1-9][0-9]{0,17}"))))throw PcException.invalid("须明确已登录用户或稳定用户ID受众");
            long pv=store.data(provider).get("configurationVersion") instanceof Number n?n.longValue():provider.getVersion();Map<String,Object> data=new LinkedHashMap<>();data.put("modelId",String.valueOf(model.getId()));data.put("modelVersion",model.getVersion());data.put("modelDefinitionVersion",PcSub2ApiPolicy.modelDefinition(store.data(model),model.getVersion()));data.put("releaseKind","CHAT");data.put("providerVersion",pv);data.put("secretVersion",metadata.activeVersion());if(PcSub2ApiPolicy.imagesVerified(store.data(model),model.getVersion(),store.data(provider),pv,metadata.activeVersion()))data.put("imageVerification",store.data(model).get("imageVerification"));data.put("audience",audience);data.put("userIds",users.stream().map(String::valueOf).toList());data.put("defaultModel",Boolean.TRUE.equals(input.get("defaultModel")));
            clearDefault(store,"CHAT",Boolean.TRUE.equals(input.get("defaultModel")),"model:"+model.getId());PcRecord release=store.mapper.findKey(PcTable.MODEL_RELEASE,"model:"+model.getId(),true);if(release==null)release=store.insert(PcTable.MODEL_RELEASE,null,user,model.getId(),null,null,"MODEL_RELEASE","PUBLISHED","model:"+model.getId(),data);else{if(!input.containsKey("releaseVersion"))throw new PcException(428,"PC_VERSION_REQUIRED","重新发布须核对当前releaseVersion");store.version(release,PcJson.number(input,"releaseVersion"));data.put("releaseDefinitionVersion",release.getVersion()+1);release.setState("PUBLISHED");store.save(PcTable.MODEL_RELEASE,release,data);}return store.view(release);
        });
    }
}
